(function(root){
  function urlKey(s){try{const u=new URL(s);u.hash='';for(const k of [...u.searchParams.keys()])if(/^(utm_|ref$|source$)/i.test(k))u.searchParams.delete(k);return u.href}catch{return String(s)}}
  function merge(db,incoming){const byURL=new Map(db.jobs.map(j=>[urlKey(j.url),j]));let added=0;for(const job of incoming){if(!job||!job.id||!job.title||!job.company||!job.location||!Array.isArray(job.skills)||!/^https:\/\//.test(job.url))continue;const old=byURL.get(urlKey(job.url));if(old){Object.assign(old,job,{id:old.id,description:old.customDescription||job.description||old.description,closed:old.localClosed??job.closed});}else{db.jobs.unshift({...job,fromFeed:true});byURL.set(urlKey(job.url),db.jobs[0]);added++;}}return added;}
  async function load(){const r=await fetch('./api/jobs',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Daily feed is unavailable. Saved jobs are unchanged.');const feed=await r.json();if(!Array.isArray(feed.jobs))throw Error('Invalid feed response');return feed;}
  root.JobFeed={merge,load,urlKey};
})(typeof window!=='undefined'?window:globalThis);
JobFeed.importReport=function(report){if(!Array.isArray(report.jobs))throw Error('The report must contain a jobs array.');return report.jobs.slice(0,100).map((raw,i)=>{const url=JobFeed.urlKey(raw.url);let parsed;try{parsed=new URL(url);}catch{return null;}if(parsed.protocol!=='https:'||parsed.username||parsed.password||!raw.title||!raw.company||!raw.location)return null;let hash=2166136261;for(const c of url){hash^=c.charCodeAt(0);hash=Math.imul(hash,16777619);}return {id:'spark-'+(hash>>>0).toString(16),title:String(raw.title).slice(0,250),company:String(raw.company).slice(0,250),location:String(raw.location).slice(0,250),mode:['Remote','Hybrid','On-site'].includes(raw.mode)?raw.mode:'Not stated',experience:String(raw.experience||'Not stated').slice(0,250),level:/intern|fresher|junior|graduate|trainee/i.test(raw.title+' '+raw.experience)?'early':'unknown',family:/data.?analyst/i.test(raw.title)?'Data Analyst':/data.?scien/i.test(raw.title)?'Data Science':/python/i.test(raw.title)?'Python':/llm|generative/i.test(raw.title)?'Generative AI':'AI/ML',skills:Array.isArray(raw.skills)?raw.skills.filter(x=>typeof x==='string').slice(0,20):[],url,description:String(raw.description||'').slice(0,8000),posted:'',deadline:'',verified:false,checked:'',firstSeen:new Date().toISOString(),note:'Imported Gemini Spark report. Details are unverified until the source is checked.'};}).filter(Boolean);};
